import React, { useState } from "react";

export default function App() {
  const [screen, setScreen] = useState("home");
  const [feeling, setFeeling] = useState("");

  return (
    <div dir="rtl" style={{ padding: 20, fontFamily: "Arial" }}>

      {screen === "home" && (
        <div>
          <h1>מה בטוח לי לאכול היום?</h1>

          <h3>איך אתה מרגיש היום?</h3>
          <button onClick={() => setFeeling("טוב")}>טוב</button>
          <button onClick={() => setFeeling("סביר")}>סביר</button>
          <button onClick={() => setFeeling("לא טוב")}>לא טוב</button>

          <p>מצב נוכחי: {feeling}</p>

          <h3>מה כדאי לך לאכול היום:</h3>
          <ul>
            <li>אורז עם עוף</li>
            <li>מרק ירקות</li>
            <li>חביתה</li>
          </ul>

          <br />
          <button onClick={() => setScreen("add")}>הוספת ארוחה</button>
        </div>
      )}

      {screen === "add" && (
        <div>
          <h1>הוספת ארוחה</h1>

          <input placeholder="מה אכלת?" />

          <br /><br />

          <button onClick={() => setScreen("home")}>חזור</button>
        </div>
      )}

    </div>
  );
}
